"""Original vector assets matching LittleGod's existing illustrated palette."""
from pathlib import Path
r=Path(__file__).resolve().parents[1]/'assets/kingdom'
def svg(key,body):
 (r/(key+'.svg')).write_text('<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><defs><linearGradient id="stone" x2=".8" y2="1"><stop stop-color="#d4d8bf"/><stop offset="1" stop-color="#728b80"/></linearGradient><linearGradient id="roof" x2=".5" y2="1"><stop stop-color="#87b5b3"/><stop offset="1" stop-color="#365b69"/></linearGradient></defs><ellipse cx="96" cy="158" rx="83" ry="19" fill="#102c38" opacity=".22"/>'+body+'</svg>\n',encoding='utf-8')
svg('barracks','<path d="M25 155V87l70-22 73 23v67l-73 22z" fill="url(#stone)" stroke="#425957" stroke-width="4"/><path d="M17 91l73-50 87 46-74 26z" fill="url(#roof)" stroke="#314c57" stroke-width="4"/><path d="M95 113v64l73-22V88z" fill="#6d8e88"/><path d="M111 167v-33q12-25 25-5v32" fill="#243f49"/><path d="M43 127h20v22H43z" fill="#304e58"/><path d="M35 74V24m0 4h36l-8 12 8 12H35" fill="#e2b768" stroke="#725a39" stroke-width="4"/><path d="M144 109l16 35m-1-38-17 40" stroke="#ecdba5" stroke-width="4"/>')
