for kind,color,weapon in [('militia','#6eaaa3','<path d="M137 60l17-35 5 6-16 36-12 4z" fill="#e9dcb5"/>'),('spearman','#6a8baf','<path d="M144 155V26m-7 7 7-20 8 20z" fill="#e0d7b8" stroke="#88765a" stroke-width="4"/>'),('archer','#8ba36a','<path d="M139 58q47 33 0 83l12-42z" fill="none" stroke="#ddbc7a" stroke-width="5"/>')]:
 body=f'<path d="M72 139l-4 28m43-28 9 28" stroke="#334b54" stroke-width="16" stroke-linecap="round"/><path d="M62 85q32-18 61 3l10 55H55z" fill="{color}" stroke="#365661" stroke-width="4"/><circle cx="94" cy="63" r="24" fill="#e2bc8f"/><path d="M66 65V48q27-35 55 0v17l-28-12z" fill="#c3d1c5" stroke="#3b5961" stroke-width="4"/><path d="M91 60v15m11-14v4" stroke="#344c4c" stroke-width="3"/><path d="M54 96l27 10v31l-26 13-15-25z" fill="#d8b969" stroke="#596a63" stroke-width="4"/>'+weapon
 svg(kind,body);svg(kind+'_kit',body)
